import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { captureGoldenScores } from "./goldenDataset";

/**
 * Byte-identity proof for the WP4 metric redesign (PR10 rename, PR11 flag-off
 * path). fixtures/scores-v2-golden.json was generated by running
 * captureGoldenScores() against the PRE-rename metrics.ts at main fba8066,
 * before any WP4 change landed. This test recomputes the same capture with the
 * current code and compares the serialized JSON character for character, so:
 *
 *  - PR10 (quality renamed to toolCallReliability, evidence classes declared)
 *    provably moved no score, confidence grade, tier, or classification.
 *  - PR11 (re-weight behind VAULT_SCORING_V3) provably reproduces the same
 *    bytes with the flag off, which is the default.
 *
 * If this test fails, a score the owner reads changed silently. Do not update
 * the fixture to make it pass; find the change that moved a number.
 */

const here = dirname(fileURLToPath(import.meta.url));
const fixturePath = join(here, "fixtures", "scores-v2-golden.json");

describe("score golden (v2 baseline from main fba8066)", () => {
  // Pin the flag OFF regardless of the shell this suite runs in, so the test
  // asserts exactly the claim: unset or "0" reproduces the baseline bytes.
  let saved: string | undefined;
  beforeEach(() => {
    saved = process.env.VAULT_SCORING_V3;
    delete process.env.VAULT_SCORING_V3;
  });
  afterEach(() => {
    if (saved === undefined) delete process.env.VAULT_SCORING_V3;
    else process.env.VAULT_SCORING_V3 = saved;
  });

  it("reproduces the pre-WP4 scores byte for byte with the flag unset", () => {
    const fixture = readFileSync(fixturePath, "utf8");
    const current = `${JSON.stringify(captureGoldenScores(), null, 2)}\n`;
    expect(current).toBe(fixture);
  });

  it("reproduces the same bytes with VAULT_SCORING_V3=0 explicitly", () => {
    process.env.VAULT_SCORING_V3 = "0";
    const fixture = readFileSync(fixturePath, "utf8");
    const current = `${JSON.stringify(captureGoldenScores(), null, 2)}\n`;
    expect(current).toBe(fixture);
  });
});
